    # Send some text over the socket
    message = "Hello, World!"
    print(f"Sending '{message}'")
    s.sendall(message.encode())

finally:
    print("Closing socket")
    s.close()
```

### 2. Set up the JavaScript Script

Next, create a simple JavaScript file that will listen for incoming data on a specific port and send it back.

#### Listening JavaScript File (`listening.js`):

```javascript
const net = require('net');
const PORT = 9000; // The same port used by the Python script

const client = new net.Socket();
client.on('connect', () => {
    console.log(`Connected to ${PORT}`);
});

client.on('data', function(data) {
    const response = `Received: ${data.toString()}`;
    client.write(response);
});

client.on('end', function() {
    console.log('Client disconnected');
});

client.connect(PORT, 'localhost', function() {
    console.log('Connected to server');
});
```

